control.onCreate:
sender.style.overflow = "auto";
sender.innerHTML = `
<style>
.site-doc { color:#26243c; background:#f7f7fc; min-height:100%; font:16px/1.6 system-ui,sans-serif; white-space:normal; overflow-wrap:anywhere; }
.site-doc * { box-sizing:border-box; }
.site-doc a { color:#46368b; text-underline-offset:.15em; }
.site-doc h1,.site-doc h2,.site-doc p { margin:0; }
.site-doc h1 { font-size:clamp(28px,5vw,48px); line-height:1.1; }
.site-doc h2 { font-size:clamp(19px,3vw,25px); line-height:1.25; }
.site-doc header { background:#302a60; color:white; }
.site-doc .wrap { max-width:950px; margin:auto; padding:clamp(20px,5vw,48px); }
.site-doc header p,.site-doc section p { margin-top:10px; }
.site-doc section { background:white; border:1px solid #e3dff2; border-radius:12px; padding:clamp(16px,3vw,26px); margin-bottom:15px; }
.site-doc pre { white-space:pre-wrap; background:#f1eef9; padding:12px; border-radius:6px; }
.site-doc button,.site-doc select,.site-doc input { font:inherit; }
.site-doc button { background:#46368b; color:#fff; border:0; border-radius:6px; padding:6px 13px; cursor:pointer; }
.site-doc :focus-visible { outline:2px solid #7c63d2; outline-offset:3px; }
.site-doc fieldset { border:1px solid #d9d1ef; border-radius:8px; margin:12px 0 0; min-width:0; }
.site-doc table { width:100%; text-align:left; border-collapse:collapse; margin-top:10px; }
.site-doc th,.site-doc td { padding:6px; border-bottom:1px solid #e3dff2; }

.site-doc .admin-skins { display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
.site-doc .admin-skins button { max-width:100%; background-color:transparent; background-size:100% 100%; color:#102342; font-weight:700; }
.site-doc .admin-skins button[aria-pressed="true"] { outline:2px solid #46368b; outline-offset:2px; }
.site-doc .admin-checks { display:grid; gap:8px; grid-template-columns:repeat(auto-fit,minmax(min(100%,145px),1fr)); margin-block:8px; }
.site-doc .admin-skins [data-skin="LRBtn1"] { width:184px; min-height:48px; background-image:url(data:image/png;base64,); }
.site-doc .admin-skins [data-skin="LRBtn2"] { width:180px; min-height:44px; background-image:url(data:image/png;base64,); }
.site-doc .admin-skins [data-skin="LRBtn7"] { width:121px; min-height:51px; background-image:url(data:image/png;base64,); }

.site-doc .component-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,275px),1fr)); gap:12px; margin-top:12px; }
.site-doc .advanced-edit { border:1px solid #ddd6ef; border-radius:8px; padding:12px; min-width:0; }
.site-doc .advanced-edit h3 { margin:0; }
.site-doc .edit-configuration, .site-doc .edit-metrics { font-size:13px; color:#4e4c63; }
.site-doc .edit-surface { min-height:48px; margin-top:8px; padding:8px; border:1px solid #bcb3d4; border-radius:5px; white-space:pre-wrap; overflow-wrap:anywhere; overflow-y:auto; }

</style>
<main class="site-doc" lang="en"><header><div class="wrap"><h1>Examples</h1><p>Try page interactions and front-end controls from ProjectAdmin.</p><p><a class="admin-jump" href="#admin-controls" style="color:white">Jump to the ProjectAdmin controls</a> &middot; <a class="admin-jump" href="#advanced-edit" style="color:white">Try the advanced Edit component</a></p></div></header><div class="wrap"><section id="layers"><h2>Switch between page views</h2><p>Named layers let a page reveal one view while retaining the surrounding interface. Try switching this preview between a compact summary and a detail view.</p>
 <fieldset><legend>Preview layout</legend><button type="button" data-view="summary" aria-pressed="true">Summary</button> <button type="button" data-view="details" aria-pressed="false">Details</button>
 <p data-layer="summary">Three pages are ready to publish.</p><p data-layer="details" hidden>Home, Features, and Examples are ready to publish. Each has its own page directory.</p></fieldset></section><section id="themes"><h2>Change the appearance</h2><p>ePage skins define the appearance of controls. Use this preview to see how the same panel reads in two palettes.</p>
 <fieldset id="theme-preview"><legend>Preview palette</legend><label>Palette <select id="palette"><option value="light">Light</option><option value="dark">Dark</option></select></label><p>Project preview</p></fieldset></section><section id="table"><h2>Filter rows in a table</h2><p>This browser-only example uses sample data to demonstrate filtering and rendering a result set. A Task Set can supply data from eServer when an application needs a server-side lookup.</p>
 <fieldset><legend>Sample data</legend><label>Filter pages <input id="row-filter" type="search" placeholder="Search by page name"></label>
 <table><thead><tr><th scope="col">Page</th><th scope="col">Type</th></tr></thead><tbody><tr><td>Home</td><td>Overview</td></tr><tr><td>Features</td><td>Reference</td></tr><tr><td>Tutorials</td><td>Guide</td></tr></tbody></table><p id="row-count" aria-live="polite">3 pages</p></fieldset></section>
<section id="admin-controls">
  <h2>ProjectAdmin front-end controls</h2>
  <p>These browser-only examples adapt the control patterns in ProjectAdmin's <code>samples/button1</code> and <code>samples/button2</code>.</p>
  <fieldset><legend>Skinned buttons</legend>
    <div class="admin-skins"><button type="button" data-skin="LRBtn1" aria-pressed="false">Blue capsule</button> <button type="button" data-skin="LRBtn2" aria-pressed="false">Green highlight</button> <button type="button" data-skin="LRBtn7" aria-pressed="false">Rounded blue</button></div>
    <p id="skin-status" role="status">Choose a button to see its ePage skin name.</p>
    <p>In the original Studio examples, each Button has a <code>backgroundSkin</code>. The preview uses those same PNG assets. The corresponding skin XML defines the resizable region and the content area.</p>
  </fieldset>
  <fieldset id="admin-checkboxes"><legend>Checkboxes in a layout</legend>
    <div class="admin-checks"><label><input type="checkbox"> Design</label><label><input type="checkbox"> JavaScript</label><label><input type="checkbox"> Publishing</label><label><input type="checkbox"> Review</label></div>
    <button id="clear-admin-checks" type="button">Clear selection</button>
    <p id="checkbox-status" role="status">0 selected</p>
    <p>The Studio example combines CheckBox controls with horizontal and vertical layouts. This adaptation adds a selection count and clear button so you can try the front-end behavior directly.</p>
  </fieldset>
</section>

<section id="advanced-edit">
  <h2>One editor component, two configurations</h2>
  <p>This browser example adapts Faith's multiline Edit component. Type or load a draft to see each instance grow until it reaches its height limit. Focus and editing state are independent.</p>
  <div class="component-grid">
    <div class="advanced-edit" data-max-height="160px" data-font-size="17px">
      <h3 id="draft-label">Page composer</h3>
      <p class="edit-configuration">Maximum height 160 px</p>
      <div class="edit-surface" contenteditable="plaintext-only" role="textbox" aria-multiline="true" aria-labelledby="draft-label"></div>
      <p class="edit-metrics"><span data-edit-count>0 characters</span> &middot; <span data-edit-height></span> &middot; <span data-edit-focus>Not focused</span></p>
      <p><button type="button" data-load-draft>Load sample draft</button> <button type="button" data-clear-draft>Clear</button></p>
    </div>
    <div class="advanced-edit" data-max-height="92px" data-font-size="15px">
      <h3 id="dialog-label">Dialog composer</h3>
      <p class="edit-configuration">Maximum height 92 px</p>
      <div class="edit-surface" contenteditable="plaintext-only" role="textbox" aria-multiline="true" aria-labelledby="dialog-label"></div>
      <p class="edit-metrics"><span data-edit-count>0 characters</span> &middot; <span data-edit-height></span> &middot; <span data-edit-focus>Not focused</span></p>
      <p><button type="button" data-load-draft>Load sample draft</button> <button type="button" data-clear-draft>Clear</button></p>
    </div>
  </div>
  <p><a href="./tutorials?v=components#build-a-component">See the ePage properties, methods, and events behind this pattern</a></p>
</section>
</div></main>`;

const views = sender.querySelectorAll("[data-view]");
for (const button of views) {
    button.addEventListener("click", function () {
        const selected = button.dataset.view;
        for (const option of views) {
            option.setAttribute("aria-pressed", String(option.dataset.view === selected));
        }
        for (const panel of sender.querySelectorAll("[data-layer]")) {
            panel.hidden = panel.dataset.layer !== selected;
        }
    });
}
sender.querySelector("#palette").addEventListener("change", function () {
    const preview = sender.querySelector("#theme-preview");
    const dark = this.value === "dark";
    preview.style.backgroundColor = dark ? "#302a60" : "";
    preview.style.color = dark ? "#ffffff" : "";
});
sender.querySelector("#row-filter").addEventListener("input", function () {
    const query = this.value.trim().toLowerCase();
    let count = 0;
    for (const row of sender.querySelectorAll("tbody tr")) {
        row.hidden = !row.cells[0].textContent.toLowerCase().includes(query);
        if (!row.hidden) count++;
    }
    sender.querySelector("#row-count").textContent = count === 1 ? "1 page" : count + " pages";
});

const skinButtons = sender.querySelectorAll("[data-skin]");
for (const button of skinButtons) {
    button.addEventListener("click", function () {
        for (const option of skinButtons) {
            option.setAttribute("aria-pressed", String(option === button));
        }
        sender.querySelector("#skin-status").textContent = "Selected skin: " + button.dataset.skin;
    });
}

const checkboxes = sender.querySelector("#admin-checkboxes");
const checkboxInputs = [...checkboxes.querySelectorAll("input")];
function showSelectionCount() {
    const count = checkboxInputs.filter(input => input.checked).length;
    checkboxes.querySelector("#checkbox-status").textContent = count + " selected";
}
checkboxes.addEventListener("change", showSelectionCount);
checkboxes.querySelector("#clear-admin-checks").addEventListener("click", function () {
    for (const input of checkboxInputs) input.checked = false;
    showSelectionCount();
});

function initAdvancedEdit(root) {
    const surface = root.querySelector(".edit-surface");
    const count = root.querySelector("[data-edit-count]");
    const height = root.querySelector("[data-edit-height]");
    const focus = root.querySelector("[data-edit-focus]");
    surface.style.maxHeight = root.dataset.maxHeight;
    surface.style.fontSize = root.dataset.fontSize;

    root.getEditText = function () {
        return surface.innerText;
    };
    root.setEditText = function (text) {
        surface.textContent = text;
        updateCount();
    };

    function updateCount() {
        count.textContent = Array.from(root.getEditText()).length + " characters";
    }
    surface.addEventListener("input", updateCount);
    surface.addEventListener("focus", () => { focus.textContent = "Focused"; });
    surface.addEventListener("blur", () => { focus.textContent = "Not focused"; });
    const observer = new ResizeObserver(() => {
        height.textContent = Math.round(surface.getBoundingClientRect().height) + " px";
    });
    observer.observe(surface);
    root.querySelector("[data-load-draft]").addEventListener("click", () => {
        root.setEditText([
            "Plan the next update:",
            "Review the page layout.",
            "Check the controls in Explorer.",
            "Try the editor on a narrow screen.",
            "Publish and test the result."
        ].join("\n"));
    });
    root.querySelector("[data-clear-draft]").addEventListener("click", () => {
        root.setEditText("");
        surface.focus();
    });
}
for (const root of sender.querySelectorAll(".advanced-edit")) {
    initAdvancedEdit(root);
}
